CREATE view  RASID_KHARID as SELECT     NUMBER, TAG AS htag, TAG - 11 AS Dtag, ANBAR, NUMBER1, DATE_N, TAH, MAS, VAS, N_S, CUST_NO, MOLAH, M_NAGHD, MABL_VAR, MOIN_VAR,   MABL_HAV, MOIN_HAV, MABL_HAZ, MOIN_HAZ, TAKHFIF, MOIN_KHF, ANBARF, FNUMCO, USER_NAME, TICMBAA, MBAA, HMBAA, DEPATMAN, SHIFT,   CUST_KIND, OKF, SADER, SHARAYET, SGN1, SGN2, SGN3, SGN4, TAMIR, TKHF, ARZD, ARZKIND, CDDATE, CDTIME, OKDATE, OKTIME, JAY, sgn1usid,    sgn2usid , sgn3usid,UID FROM dbo.HEAD_LST WHERE     (TAG = 12) AND (SADER = 0 OR   SADER IS NULL)
